package com.cestasdamel.erp.repository; import com.cestasdamel.erp.model.Sale; import org.springframework.data.jpa.repository.*; import java.time.Instant; import java.math.BigDecimal; import java.util.*;
public interface SaleRepository extends JpaRepository<Sale,Long>{ @EntityGraph(attributePaths="items") List<Sale> findAllByOrderBySoldAtDesc(); @Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @EntityGraph(attributePaths="items") @Query("select s from Sale s where s.id=:id") Optional<Sale> lockDetailedById(Long id); @Query("select coalesce(sum(s.total),0) from Sale s where s.status='CONFIRMED' and s.soldAt>=:from and s.soldAt<:to") BigDecimal sumBetween(Instant from,Instant to); @Query("select count(s) from Sale s where s.status='CONFIRMED' and s.soldAt>=:from and s.soldAt<:to") long countConfirmedBetween(Instant from,Instant to); }
